// thousands separators only in proper groups, the decimal comma when detected, and % only where allowed (screen failure)
function bmNumber(v, decComma, allowPct = false) {
  let s = String(v ?? '').trim(); if (!s || /^(na|n\/a|nr|-|—|null|none)$/i.test(s)) return null;
  const pct = /%$/.test(s); if (pct && !allowPct) return false;
  s = s.replace(/\s*%$/, '');
  const g = s.match(new RegExp(`^[+-]?[1-9]\\d{0,2}([${decComma ? '\\.' : ','} \\u00a0\\u202f])\\d{3}(?:\\1\\d{3})*(?:${decComma ? ',' : '\\.'}\\d+)?$`));
  if (g) s = s.split(g[1]).join('');
  if (decComma) s = s.replace(',', '.');
  if (!/^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(s)) return false;
  const n = Number(s); return Number.isFinite(n) ? { n, pct } : false;
}

